inline constexpr size_t chunkCount = sizeof(chunks) / sizeof(chunks[0]);

// Reassemble the complete JSON text from all chunks
inline std::string text() {
    std::string out;
    size_t total = 0;
    for (auto const& chunk : chunks) total += chunk.size();
    out.reserve(total);
    for (auto const& chunk : chunks) out.append(chunk);
    return out;
}

